contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint preBal = address(c).balance;
        bool reverted;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        reverted = false;
        assert((ownerBefore == address(this))
            ? (!reverted && address(c).balance == 0)
            : (!reverted || address(c).balance == preBal));
    }
}

